function i(n){if(!n)return"";const e=n.toLowerCase();return e.includes("cookie")||e.includes("unauthorized")||e.includes("401")||e.includes("login")||e.includes("auth")?"站点登录已失效，请在「站点」页重新配置 Cookie":e.includes("deadline")||e.includes("timeout")||e.includes("timed out")?"站点响应超时，请稍后重试":e.includes("404")||e.includes("not found")||e.includes("no such")?"站点页面结构变更，待校准":e.includes("502")||e.includes("503")||e.includes("504")||e.includes("unavailable")||e.includes("server error")?"站点暂时不可用":"该站点获取失败"}export{i as f};
